package compliance

// CIS Amazon Web Services Foundations Benchmark v7.0.0. Recommendation numbers and titles follow the benchmark as
// published by CIS (April 2026) and implemented by Tenable's v7.0.0 audit files and Prowler's cis_7.0_aws mapping.
// cisecurity.org also lists a v7.1.0 whose recommendation list isn't public yet; this pack moves to it once it can be
// verified. Controls whose evidence lives in the account (root user, IAM users and their credentials, Organizations,
// AWS Config, Security Hub, CloudWatch alarms) are manual: a design declaring some of them doesn't prove the rest of
// the account does.

const (
	awsIAM        = "Identity and Access Management"
	awsS3         = "Storage - S3"
	awsRDS        = "Storage - RDS"
	awsEFS        = "Storage - EFS"
	awsLogging    = "Logging"
	awsMonitoring = "Monitoring"
	awsNetwork    = "Networking"
	awsAccount    = "Check it in the AWS console (IAM credential report, account settings) or with a CIS scanner (AWS Security Hub's CIS standard, Prowler's cis_7.0_aws), then attest it. "
	awsAlarm      = "Create a CloudWatch Logs metric filter on the log group of a multi-Region CloudTrail trail, a CloudWatch alarm on it and an SNS topic with an active subscriber (aws_cloudwatch_log_metric_filter, aws_cloudwatch_metric_alarm, aws_sns_topic_subscription; the benchmark gives the filter pattern). Nimbo doesn't verify filter patterns; attest once the alarm fires in a test. Filter: "
)

var (
	awsSecurityGroups = []string{"aws_security_group", "aws_default_security_group", "aws_security_group_rule", "aws_vpc_security_group_ingress_rule"}
	awsRDSDatabases   = []string{"aws_db_instance", "aws_rds_cluster", "aws_rds_cluster_instance"}
	awsTrail          = []string{"aws_cloudtrail"}
)

func init() {
	Register(Framework{
		ID:       "cis-aws-7.0",
		Name:     "CIS Amazon Web Services Foundations Benchmark",
		Version:  "7.0.0",
		Platform: "aws",
		Source:   "https://www.cisecurity.org/benchmark/amazon_web_services",
		Controls: []Control{
			// 2 Identity and Access Management
			{ID: "2.1.1", Title: "Ensure centralized root access in AWS Organizations", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "In the Organizations management account, enable centralized root access (root credentials management and privileged root actions) for IAM, then remove root credentials from member accounts."},
			{ID: "2.1.2", Title: "Ensure authorization guardrails for all AWS Organization accounts", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Attach service control policies (and resource control policies) that set the guardrails every member account must stay within."},
			{ID: "2.1.3", Title: "Ensure Organizations management account is not used for workloads", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Deploy this design to a member account, never to the Organizations management account."},
			{ID: "2.1.4", Title: "Ensure Organizational Units are structured by environment and sensitivity", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Group accounts into OUs by environment (prod, non-prod) and data sensitivity so policies apply per OU."},
			{ID: "2.1.5", Title: "Ensure delegated admin manages AWS Organizations policies", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Register a delegated administrator account for Organizations policy management instead of using the management account."},
			{ID: "2.1.6", Title: "Ensure delegated admins manage AWS Organizations-integrated services", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Register delegated administrators for integrated services (Security Hub, GuardDuty, Config, IAM Access Analyzer…)."},
			{ID: "2.2", Title: "Maintain current AWS account contact details", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Keep the account's primary contact (email and phone) current, on a shared mailbox rather than one person's address."},
			{ID: "2.3", Title: "Ensure security contact information is registered", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Register the security alternate contact (aws_account_alternate_contact with alternate_contact_type = \"SECURITY\" can manage it in an account-level workflow)."},
			{ID: "2.4", Title: "Ensure no 'root' user account access key exists", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "The credential report shows no access keys for <root_account>; delete any. Terraform can't manage root credentials."},
			{ID: "2.5", Title: "Ensure MFA is enabled for the 'root' user account", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Enable MFA on the root user (or remove root credentials with centralized root access)."},
			{ID: "2.6", Title: "Ensure hardware MFA is enabled for the 'root' user account", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Use a hardware MFA device or FIDO security key for the root user."},
			{ID: "2.7", Title: "Eliminate use of the 'root' user for administrative and daily tasks", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "The credential report shows no recent root password or key use; daily work goes through IAM Identity Center or IAM roles."},
			{ID: "2.8", Title: "Ensure IAM password policy requires minimum length of 14 or greater", Section: awsIAM,
				Rules: []string{"bp_iam_password_length"}, AppliesTo: []string{"aws_iam_account_password_policy"},
				Guidance: "Nimbo checks minimum_password_length on the aws_iam_account_password_policy in the design. Without that resource the control doesn't apply here: manage the account's password policy in an account-level workflow or check it in IAM account settings."},
			{ID: "2.9", Title: "Ensure IAM password policy prevents password reuse", Section: awsIAM,
				Rules: []string{"bp_iam_password_reuse"}, AppliesTo: []string{"aws_iam_account_password_policy"},
				Guidance: "Nimbo checks that the aws_iam_account_password_policy in the design sets password_reuse_prevention to 24. Without that resource the control doesn't apply here."},
			{ID: "2.10", Title: "Ensure multi-factor authentication (MFA) is enabled for all IAM users that have a console password", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Every IAM user with a console password (aws_iam_user_login_profile) has an MFA device. Prefer IAM Identity Center users, which enforce MFA centrally."},
			{ID: "2.11", Title: "Ensure credentials unused for 45 days or more are disabled", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Disable console passwords and deactivate access keys unused for 45 days (credential report: password_last_used, access_key_N_last_used_date)."},
			{ID: "2.12", Title: "Ensure access keys are rotated every 90 days or less", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Rotate IAM user access keys at least every 90 days; prefer roles, which issue temporary credentials. An aws_iam_access_key in a design also lands its secret in the Terraform state."},
			{ID: "2.13", Title: "Ensure IAM users receive permissions only through groups", Section: awsIAM,
				Rules: []string{"bp_iam_user_policy"}, AppliesTo: []string{"aws_iam_user_policy", "aws_iam_user_policy_attachment", "aws_iam_policy_attachment", "aws_iam_user_policies_exclusive", "aws_iam_user_policy_attachments_exclusive"},
				Guidance: "Nimbo flags inline user policies, user policy attachments and shared attachments that list users. Policies attached to users outside this design aren't seen."},
			{ID: "2.14", Title: "Ensure IAM policies that allow full \"*:*\" administrative privileges are not attached", Section: awsIAM,
				Rules: []string{"bp_iam_wildcard", "bp_iam_admin_attached"},
				AppliesTo: []string{"aws_iam_policy", "aws_iam_role_policy", "aws_iam_user_policy", "aws_iam_group_policy", "aws_iam_role",
					"aws_iam_role_policy_attachment", "aws_iam_user_policy_attachment", "aws_iam_group_policy_attachment", "aws_iam_policy_attachment",
					"aws_iam_role_policy_attachments_exclusive", "aws_iam_user_policy_attachments_exclusive", "aws_iam_group_policy_attachments_exclusive"},
				Guidance: "Nimbo flags policies in the design that allow \"*\" on \"*\" (inline JSON, jsonencode or an aws_iam_policy_document they use) and attachments of the AWS managed AdministratorAccess policy. Statements built from variables can't be judged."},
			{ID: "2.15", Title: "Ensure a support role has been created to manage incidents with AWS Support", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Have an IAM role with the AWSSupportAccess managed policy attached (aws_iam_role_policy_attachment) that your incident responders can assume."},
			{ID: "2.16", Title: "Ensure IAM instance roles are used for AWS resource access from instances", Section: awsIAM, Manual: true,
				Guidance: "Instances that call AWS APIs get credentials from an instance profile (iam_instance_profile on aws_instance or the launch template), not from access keys on disk. Nimbo can't see how your code authenticates; attest it once confirmed."},
			{ID: "2.17", Title: "Ensure that all expired SSL/TLS certificates stored in AWS IAM are removed", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "aws iam list-server-certificates shows no expired certificate; prefer ACM, which renews certificates."},
			{ID: "2.18", Title: "Ensure that IAM External Access Analyzer is enabled for all regions", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "Create an account (or organization) analyzer in every enabled region (aws_accessanalyzer_analyzer per region provider)."},
			{ID: "2.19", Title: "Ensure IAM users are managed centrally via identity federation or AWS Organizations for multi-account environments", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "People sign in through IAM Identity Center or a federated identity provider rather than per-account IAM users."},
			{ID: "2.20", Title: "Ensure access to AWSCloudShellFullAccess is restricted", Section: awsIAM, Manual: true,
				Guidance: awsAccount + "The AWSCloudShellFullAccess managed policy isn't attached to users, groups or roles (or is denied by an SCP), since CloudShell can move files in and out of the account."},
			{ID: "2.21", Title: "Ensure AWS resource policies do not allow unrestricted access using \"Principal\": \"*\"", Section: awsIAM, Manual: true,
				Guidance: "Review the resource policies of buckets, queues, topics, keys, functions, secrets and event buses: Principal \"*\" needs a Condition that scopes it (aws:SourceArn, aws:PrincipalOrgID…). bp_public_bucket flags open bucket policies in the design; the other services aren't checked."},

			// 3 Storage
			{ID: "3.1.1", Title: "Ensure S3 Bucket Policy is set to deny HTTP requests", Section: awsS3,
				Rules: []string{"bp_s3_deny_http"}, AppliesTo: []string{"aws_s3_bucket"},
				Guidance: "Nimbo checks that every bucket in the design has a bucket policy with a Deny statement conditioned on aws:SecureTransport = false (JSON, jsonencode or an aws_iam_policy_document). Policies Nimbo can't read (templatefile, variables) are given the benefit of the doubt."},
			{ID: "3.1.2", Title: "Ensure MFA Delete is enabled on S3 buckets", Section: awsS3, Manual: true,
				Guidance: "Only the root user can turn MFA Delete on (aws s3api put-bucket-versioning with --mfa), so it is normally set outside Terraform; verify with get-bucket-versioning on each bucket and attest it."},
			{ID: "3.1.3", Title: "Ensure all data in Amazon S3 has been discovered, classified, and secured when necessary", Section: awsS3, Manual: true,
				Guidance: awsAccount + "Run Amazon Macie (aws_macie2_account plus classification jobs) over the account's buckets and act on its findings."},
			{ID: "3.1.4", Title: "Ensure that S3 is configured with 'Block Public Access' enabled", Section: awsS3,
				Rules: []string{"bp_s3_block_public_access"}, AppliesTo: []string{"aws_s3_bucket_public_access_block", "aws_s3_account_public_access_block"},
				Guidance: "Nimbo checks that every bucket- and account-level public access block in the design turns on all four settings, buckets meant to be public included. Buckets without a public access block keep the settings S3 turns on for new buckets (since April 2023) and aren't counted."},
			{ID: "3.2.1", Title: "Ensure that encryption-at-rest is enabled for RDS instances", Section: awsRDS,
				Rules: []string{"bp_unencrypted_storage"}, AppliesTo: []string{"aws_db_instance", "aws_rds_cluster"},
				Guidance: "Nimbo checks storage_encrypted on DB instances and clusters. Read replicas, Aurora instances (encrypted through their cluster) and clusters restored from a snapshot inherit their source's encryption and aren't flagged."},
			{ID: "3.2.2", Title: "Ensure the Auto Minor Version Upgrade feature is enabled for RDS instances", Section: awsRDS,
				Rules: []string{"bp_rds_minor_upgrade"}, AppliesTo: awsRDSDatabases,
				Guidance: "Nimbo flags DB instances, cluster instances and clusters that set auto_minor_version_upgrade = false (it defaults to true)."},
			{ID: "3.2.3", Title: "Ensure that RDS instances are not publicly accessible", Section: awsRDS,
				Rules: []string{"bp_rds_public"}, AppliesTo: awsRDSDatabases,
				Guidance: "Nimbo flags DB instances, cluster instances and clusters that set publicly_accessible = true. A value from a variable can't be judged."},
			{ID: "3.2.4", Title: "Ensure Multi-AZ deployments are used for enhanced availability in Amazon RDS", Section: awsRDS,
				Rules: []string{"bp_rds_multi_az"}, AppliesTo: []string{"aws_db_instance"},
				Guidance: "Nimbo checks multi_az = true on DB instances (read replicas excluded). Aurora clusters get availability from instances in several zones: check that each has a reader in another Availability Zone."},
			{ID: "3.3.1", Title: "Ensure that encryption is enabled for EFS file systems", Section: awsEFS,
				Rules: []string{"bp_unencrypted_storage"}, AppliesTo: []string{"aws_efs_file_system"},
				Guidance: "Nimbo checks encrypted = true on every EFS file system in the design."},

			// 4 Logging
			{ID: "4.1", Title: "Ensure CloudTrail is enabled in all regions", Section: awsLogging,
				Rules: []string{"bp_cloudtrail_multi_region"}, AppliesTo: awsTrail,
				Guidance: "Nimbo checks that each trail in the design is multi-Region, logging and records all read and write management events. A design without a trail doesn't show the account's trail (often an organization trail): check it in CloudTrail."},
			{ID: "4.2", Title: "Ensure CloudTrail log file validation is enabled", Section: awsLogging,
				Rules: []string{"bp_cloudtrail_log_validation"}, AppliesTo: awsTrail,
				Guidance: "Nimbo checks enable_log_file_validation = true on each trail in the design."},
			{ID: "4.3", Title: "Ensure AWS Config is enabled in all regions", Section: awsLogging, Manual: true,
				Guidance: awsAccount + "Record all resource types (including global ones in one region) with an aws_config_configuration_recorder and delivery channel in every enabled region, or deploy it organization-wide."},
			{ID: "4.4", Title: "Ensure that server access logging is enabled on the CloudTrail S3 bucket", Section: awsLogging,
				Rules: []string{"bp_cloudtrail_bucket_logging"}, AppliesTo: awsTrail,
				Guidance: "Nimbo checks that the bucket each trail writes to has an aws_s3_bucket_logging when that bucket is in the design. A bucket outside the design (a name or variable) can't be checked: verify it in S3."},
			{ID: "4.5", Title: "Ensure CloudTrail logs are encrypted at rest using KMS CMKs", Section: awsLogging,
				Rules: []string{"bp_cloudtrail_kms"}, AppliesTo: awsTrail,
				Guidance: "Nimbo checks that each trail in the design sets kms_key_id."},
			{ID: "4.6", Title: "Ensure rotation for customer-created symmetric CMKs is enabled", Section: awsLogging,
				Rules: []string{"bp_kms_rotation"}, AppliesTo: []string{"aws_kms_key"},
				Guidance: "Nimbo checks enable_key_rotation = true on symmetric encryption keys; asymmetric, HMAC and custom key store keys can't rotate automatically and aren't flagged."},
			{ID: "4.7", Title: "Ensure VPC flow logging is enabled in all VPCs", Section: awsLogging,
				Rules: []string{"bp_vpc_flow_logs"}, AppliesTo: []string{"aws_vpc", "aws_default_vpc"},
				Guidance: "Nimbo checks that every VPC in the design has an aws_flow_log on its vpc_id recording REJECT or ALL traffic. VPCs created outside the design (including other regions' default VPCs) aren't seen."},
			{ID: "4.8", Title: "Ensure that object-level logging for write events is enabled for S3 buckets", Section: awsLogging,
				Rules: []string{"bp_cloudtrail_s3_write_events"}, AppliesTo: awsTrail,
				Guidance: "Nimbo checks that a trail in the design records S3 object-level write data events (basic event selector on AWS::S3::Object, or an advanced selector on Data events of AWS::S3::Object). It doesn't check which buckets the selector covers."},
			{ID: "4.9", Title: "Ensure that object-level logging for read events is enabled for S3 buckets", Section: awsLogging,
				Rules: []string{"bp_cloudtrail_s3_read_events"}, AppliesTo: awsTrail,
				Guidance: "Nimbo checks that a trail in the design records S3 object-level read data events. It doesn't check which buckets the selector covers."},
			{ID: "4.10", Title: "Ensure all AWS-managed web front-end services have access logging enabled", Section: awsLogging, Manual: true,
				Guidance: "Turn on access logs for every CloudFront distribution (logging_config), load balancer (access_logs { enabled = true }) and API Gateway stage (access_log_settings), then attest it."},

			// 5 Monitoring
			{ID: "5.1", Title: "Ensure unauthorized API calls are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "errorCode \"*UnauthorizedOperation\" or \"AccessDenied*\"."},
			{ID: "5.2", Title: "Ensure management console sign-in without MFA is monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "ConsoleLogin events with additionalEventData.MFAUsed != \"Yes\"."},
			{ID: "5.3", Title: "Ensure usage of the 'root' account is monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "userIdentity.type = \"Root\" outside AWS service events."},
			{ID: "5.4", Title: "Ensure IAM policy changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "IAM policy create, delete, version and attach/detach events."},
			{ID: "5.5", Title: "Ensure CloudTrail configuration changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "CreateTrail, UpdateTrail, DeleteTrail, StartLogging and StopLogging."},
			{ID: "5.6", Title: "Ensure AWS Management Console authentication failures are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "ConsoleLogin with errorMessage \"Failed authentication\"."},
			{ID: "5.7", Title: "Ensure disabling or scheduled deletion of customer created CMKs is monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "kms.amazonaws.com DisableKey and ScheduleKeyDeletion."},
			{ID: "5.8", Title: "Ensure S3 bucket policy changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "s3.amazonaws.com PutBucketAcl, PutBucketPolicy, PutBucketCors, PutBucketLifecycle, PutBucketReplication and their Delete* counterparts."},
			{ID: "5.9", Title: "Ensure AWS Config configuration changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "config.amazonaws.com StopConfigurationRecorder, DeleteDeliveryChannel, PutDeliveryChannel and PutConfigurationRecorder."},
			{ID: "5.10", Title: "Ensure security group changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "AuthorizeSecurityGroupIngress/Egress, RevokeSecurityGroupIngress/Egress, CreateSecurityGroup and DeleteSecurityGroup."},
			{ID: "5.11", Title: "Ensure Network Access Control List (NACL) changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "CreateNetworkAcl(Entry), DeleteNetworkAcl(Entry), ReplaceNetworkAclEntry and ReplaceNetworkAclAssociation."},
			{ID: "5.12", Title: "Ensure changes to network gateways are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "Create/Delete/Attach/DetachInternetGateway and Create/DeleteCustomerGateway."},
			{ID: "5.13", Title: "Ensure route table changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "CreateRoute(Table), ReplaceRoute(TableAssociation), DeleteRoute(Table) and DisassociateRouteTable."},
			{ID: "5.14", Title: "Ensure VPC changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "Create/DeleteVpc, ModifyVpcAttribute, VPC peering and ClassicLink events."},
			{ID: "5.15", Title: "Ensure AWS Organizations changes are monitored", Section: awsMonitoring, Manual: true,
				Guidance: awsAlarm + "organizations.amazonaws.com account, OU, policy and handshake changes."},
			{ID: "5.16", Title: "Ensure AWS Security Hub is enabled", Section: awsMonitoring, Manual: true,
				Guidance: awsAccount + "Enable Security Hub (aws_securityhub_account) in every enabled region, ideally organization-wide with a delegated administrator."},

			// 6 Networking
			{ID: "6.1.1", Title: "Ensure EBS volume encryption is enabled in all regions", Section: awsNetwork,
				Rules: []string{"bp_unencrypted_storage"}, AppliesTo: []string{"aws_ebs_volume"},
				Guidance: "The control is the account's EBS encryption-by-default setting in every region, which a design rarely holds; Nimbo checks what it can see: every aws_ebs_volume is encrypted, explicitly or through an aws_ebs_encryption_by_default in the design. Root volumes of instances aren't counted. Turn the default on per region (aws_ebs_encryption_by_default) and verify it with aws ec2 get-ebs-encryption-by-default."},
			{ID: "6.1.2", Title: "Ensure CIFS access is restricted to trusted networks to prevent unauthorized access", Section: awsNetwork,
				Rules: []string{"bp_sg_open_cifs"}, AppliesTo: awsSecurityGroups,
				Guidance: "Nimbo flags security group ingress from 0.0.0.0/0 or ::/0 whose protocol is TCP, UDP or all with a port range including 445. bp_open_ingress reports the same exposure in Problems, but it also covers SSH, RDP and database ports, so this control is graded on the 445-only rule."},
			{ID: "6.2", Title: "Ensure no Network ACLs allow ingress from 0.0.0.0/0 to remote server administration ports", Section: awsNetwork,
				Rules: []string{"bp_nacl_admin_ports"}, AppliesTo: []string{"aws_network_acl", "aws_default_network_acl", "aws_network_acl_rule"},
				Guidance: "Nimbo flags network ACL ingress rules that allow 0.0.0.0/0 or ::/0 with protocol TCP, UDP or all and a port range including 22 or 3389 (an ephemeral range such as 1024-65535 includes 3389). Rule order (a lower-numbered deny) isn't taken into account, as in the benchmark's audit."},
			{ID: "6.3", Title: "Ensure no security groups allow ingress from 0.0.0.0/0 to remote server administration ports", Section: awsNetwork,
				Rules: []string{"bp_sg_admin_ipv4"}, AppliesTo: awsSecurityGroups,
				Guidance: "Nimbo flags security group ingress from 0.0.0.0/0 with protocol TCP, UDP or all and a port range including 22 or 3389. Other administration ports of your environment aren't known to Nimbo; bp_open_ingress also covers database ports."},
			{ID: "6.4", Title: "Ensure no security groups allow ingress from ::/0 to remote server administration ports", Section: awsNetwork,
				Rules: []string{"bp_sg_admin_ipv6"}, AppliesTo: awsSecurityGroups,
				Guidance: "Nimbo flags security group ingress from ::/0 with protocol TCP, UDP or all and a port range including 22 or 3389."},
			{ID: "6.5", Title: "Ensure the default security group of every VPC restricts all traffic", Section: awsNetwork,
				Rules: []string{"bp_default_sg_closed"}, AppliesTo: []string{"aws_vpc", "aws_default_vpc", "aws_default_security_group"},
				Guidance: "Nimbo checks that every VPC in the design manages its default security group with an empty aws_default_security_group and that no rule resource adds to it. Whether resources are still attached to a default group is only visible in the account."},
			{ID: "6.6", Title: "Ensure routing tables for VPC peering are \"least access\"", Section: awsNetwork, Manual: true,
				Guidance: "Routes to a VPC peering connection (vpc_peering_connection_id) target only the subnets that need to talk to the peer, not the peer's whole CIDR. Nimbo can't tell which subnets need it; review the route tables and attest."},
			{ID: "6.7", Title: "Ensure that the EC2 Metadata Service only allows IMDSv2", Section: awsNetwork,
				Rules: []string{"bp_imdsv2"}, AppliesTo: []string{"aws_instance", "aws_launch_template", "aws_launch_configuration"},
				Guidance: "Nimbo checks metadata_options.http_tokens = \"required\" (or a disabled endpoint) on instances, launch templates and launch configurations; an account-wide aws_ec2_instance_metadata_defaults requiring tokens covers the ones that don't set it."},
			{ID: "6.8", Title: "Ensure VPC Endpoints are used for access to AWS Services", Section: awsNetwork, Manual: true,
				Guidance: "Workloads in private subnets reach AWS services (S3, DynamoDB, ECR, Secrets Manager…) through aws_vpc_endpoint gateway or interface endpoints instead of a NAT gateway or the internet. Which services a workload calls isn't visible in the design; attest once reviewed."},
		},
	})
}
